### C++

```cpp
#include <iostream>
#include <vector>
#include <bitset>
using namespace std;

const int MAXM = 20005;

int solveCase(int n, int M, const vector<int>& arr) {
    bitset<MAXM> dp;      // dp[r] = 1 表示余数 r 可达
    bitset<MAXM> mask;    // 用于截断，仅保留低 M 位

    for (int i = 0; i < M; ++i) {
        mask.set(i);
    }

    for (int num : arr) {
        int x = num % M;
        bitset<MAXM> shifted;

        if (x == 0) {
            shifted = dp;
        } else {
            // 循环左移 x 位
            shifted = ((dp << x) & mask) | (dp >> (M - x));
        }

        dp |= shifted;       // 接在已有方案后
        dp.set(x);           // 单独选取当前数
        dp &= mask;          // 仅保留低 M 位
    }

    for (int ans = M - 1; ans >= 0; --ans) {
        if (dp.test(ans)) {
            return ans;
        }
    }
    return 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n, M;
        cin >> n >> M;
        vector<int> arr(n);
        for (int i = 0; i < n; ++i) {
            cin >> arr[i];
        }
        cout << solveCase(n, M, arr) << '\n';
    }

    return 0;
}
